package com.governai.decision;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.OffsetDateTime;import java.util.UUID;@Entity @Table(name="approval")public class Approval{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="decision_request_id",nullable=false)private UUID decisionRequestId;@Column(name="reviewer_id",nullable=false)private UUID reviewerId;@Enumerated(EnumType.STRING)@JdbcTypeCode(SqlTypes.NAMED_ENUM)@Column(nullable=false,columnDefinition="approval_action_enum")private ApprovalAction action;@Column(name="original_recommendation",columnDefinition="text")private String originalRecommendation;@Column(name="final_decision",columnDefinition="text")private String finalDecision;@Column(name="reviewer_comment",columnDefinition="text")private String reviewerComment;@Column(name="reviewed_at",nullable=false)private OffsetDateTime reviewedAt;@PrePersist void create(){if(reviewedAt==null)reviewedAt=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getDecisionRequestId(){return decisionRequestId;}public void setDecisionRequestId(UUID v){decisionRequestId=v;}public UUID getReviewerId(){return reviewerId;}public void setReviewerId(UUID v){reviewerId=v;}public ApprovalAction getAction(){return action;}public void setAction(ApprovalAction v){action=v;}public String getOriginalRecommendation(){return originalRecommendation;}public void setOriginalRecommendation(String v){originalRecommendation=v;}public String getFinalDecision(){return finalDecision;}public void setFinalDecision(String v){finalDecision=v;}public String getReviewerComment(){return reviewerComment;}public void setReviewerComment(String v){reviewerComment=v;}public OffsetDateTime getReviewedAt(){return reviewedAt;}}
